#include <stdlib.h>  // free

/**
 * @brief Parses the given tokens, analyses them and asserts the annotated AST
 * renders as expected
 */
#define ASSERT_SEMANTIC_AST(expected, ...)        \
  do {                                            \
    PARSE(__VA_ARGS__);                           \
    semantics_analyze(ctx);                       \
    char* actual_ = ast_to_test_string(ctx->ast); \
    defer(free(actual_));                         \
    asserteq_str(actual_, (expected));            \
  } while (0)

/**
 * @brief Asserts that parsing and analysing the given tokens stops with the
 * given exit code
 */
#define ASSERT_SEMANTIC_ERROR(code, ...) \
  assertThrow(code, {                    \
    PARSE(__VA_ARGS__);                  \
    semantics_analyze(ctx);              \
  })

// `@main def main() = ()` as program rows
#define MAIN_DEF                                                           \
  LINE(0), TOK(AT_MAIN), TOK(DEF), ID("main"), UNIT_VALUE, TOK(ASSIGN), \
      UNIT_VALUE, EOL

// `def name() = ()` as program rows
#define EMPTY_DEF(name) \
  LINE(0), TOK(DEF), ID(name), UNIT_VALUE, TOK(ASSIGN), UNIT_VALUE, EOL

